declare(strict_types=1);require_once __DIR__.'/seo.php';$title='Heera Estate | Properties, Plots and Projects in Pakistan';$description='Find available houses, land, plots and real-estate projects with payment plans, trusted agents and a digital plot finder from Heera Estate.';$canonical=seo_url();$organization=['@context'=>'https://schema.org','@type'=>['RealEstateAgent','LocalBusiness'],'name'=>seo_site_name(),'url'=>$canonical,'logo'=>seo_url('images/home-logo.jpg'),'image'=>seo_url('images/al-rehman-garden-hero.png'),'telephone'=>getenv('HEERA_PHONE')?:'+92 300 0660446','address'=>['@type'=>'PostalAddress','addressCountry'=>'PK'],'sameAs'=>array_values(array_filter(array_map('trim',explode(',',(string)(getenv('HEERA_SOCIAL_URLS')?:'')))))];$html=(string)file_get_contents(__DIR__.'/index.html');$html=preg_replace('#<title>.*?</title>#is',seo_meta_tags(['title'=>$title,'description'=>$description,'canonical'=>$canonical,'image'=>'images/al-rehman-garden-hero.png']),$html,1)??$html;$html=preg_replace('#\s*<meta name="description"[^>]*>#i','',$html,1)??$html;$html=str_replace('</head>',"\n  ".seo_json_ld($organization)."\n  ".seo_json_ld(['@context'=>'https://schema.org','@type'=>'WebSite','name'=>seo_site_name(),'url'=>$canonical])."\n</head>",$html);try{$pdo=seo_db();seo_ensure_schema($pdo);$places=[];foreach($pdo->query("SELECT DISTINCT city AS place FROM properties WHERE status='available' UNION SELECT DISTINCT location AS place FROM projects WHERE status='published' ORDER BY place LIMIT 12")->fetchAll() as $row){$place=trim((string)$row['place']);if($place!=='')$places[$place]=seo_slugify($place);}if($places){$links='';foreach($places as $place=>$placeSlug)$links.='<a href="location/'.seo_h($placeSlug).'">'.seo_h($place).'</a>';$html=str_replace('</main>','<section class="seo-home-locations section"><div class="section-heading"><div><p class="eyebrow">Explore by area</p><h2>Popular locations</h2></div></div><div class="seo-location-links">'.$links.'</div></section></main>',$html);}}catch(Throwable $e){}$html=str_replace('</body>',seo_analytics()."\n</body>",$html);echo $html;
